import {expandedBody,expandedPortrait} from './expanded-pet-art.js';
import * as T from '../vendor/three.module.min.js';
import {PETS,petLevel} from './collection.js';
// Shared low-poly geometry/materials belong to RunnerView and are disposed once.
export function buildPet(v,pet){const type=PETS.find(p=>p.id===pet.species),s=type.id,g=new T.Group(),parts={legs:[],wings:[]},c=type.color;
 const ball=(color,x,y,z,sx,sy,sz,geo=v.ball)=>{const m=v.mesh(geo,color);m.position.set(x,y,z);m.scale.set(sx,sy,sz);g.add(m);return m;};
 const block=(color,x,y,z,w,h,d)=>v.block(g,color,x,y,z,w,h,d);
 const bird=['owl','phoenix','griffin'].includes(s),flying=bird||['sprite','dragon'].includes(s);g.userData={...parts,flying,species:s,level:petLevel(pet.xp)};
 const legacy=['dog','cat','fox','wolf','rabbit','owl','turtle','dragon','phoenix','unicorn','griffin','golem','cosmicfox','sprite'].includes(s);let shape=null;if(!legacy){shape=expandedBody(v,g,parts,type);g.userData.flying=shape.flying;g.userData.aquatic=shape.aquatic;g.userData.tails=parts.tails||[];}else if(s==='sprite'){ball(c,0,.7,0,.25,.45,.2);ball(0xffe2ba,0,1.22,0,.24,.24,.24);for(const side of [-1,1])parts.wings.push(ball(0xccfff4,side*.36,.92,.1,.3,.42,.07));ball(0xffef9e,0,1.57,0,.13,.24,.13,v.gem);}
 else if(s==='golem'){block(c,0,.65,0,.7,.65,.55);block(0xc1cec6,0,1.15,-.05,.62,.5,.5);for(const side of [-1,1]){parts.legs.push(block(c,side*.24,.17,0,.25,.35,.3));block(c,side*.5,.6,0,.25,.65,.3);}ball(0x8dfff0,0,.73,-.3,.16,.2,.08,v.gem);}
 else if(bird){ball(c,0,.75,0,.48,.65,.4);ball(s==='owl'?0xc8aa89:0xffdd8f,0,1.1,-.23,.4,.38,.18);ball(0xf7b54b,0,.93,-.48,.13,.2,.22,v.cone);for(const side of [-1,1]){parts.wings.push(ball(c,side*.5,.8,0,.2,.5,.36));parts.legs.push(block(0xe2a75b,side*.2,.15,0,.12,.3,.15));}if(s==='phoenix'){for(let i=0;i<3;i++)ball(i%2?0xffd155:0xf07753,(i-1)*.17,.5,.65,.14,.2,.65,v.cone);ball(0xffcc55,0,1.65,0,.16,.4,.16,v.cone);}if(s==='griffin'){ball(0xf1ead5,0,1.42,0,.32,.32,.32);ball(0xc39859,0,.55,.5,.38,.3,.55);}}
 else if(s==='turtle'){ball(0x477e68,0,.5,0,.6,.38,.66);ball(0xa2de85,0,.5,-.72,.26,.22,.3);for(const side of [-1,1])for(const z of [-.4,.4])parts.legs.push(ball(c,side*.49,.16,z,.2,.15,.23));for(let i=0;i<3;i++)ball(0xa3c576,(i-1)*.25,.82,0,.12,.05,.3);}
 else{const horse=s==='unicorn',dragon=s==='dragon',rabbit=s==='rabbit',cat=s==='cat',fox=['fox','cosmicfox','wolf'].includes(s);ball(c,0,.6,0,horse?.4:.43,horse?.42:.33,horse?.65:.5);ball(c,0,horse?1.17:.94,-.5,.34,horse?.44:.32,.33);ball(horse?0xf5e2ef:0xffe8d0,0,horse?1.05:.83,-.77,.23,.17,.2);
 for(const side of [-1,1]){ball(c,side*.22,rabbit?1.54:1.25,-.45,rabbit?.13:.17,rabbit?.48:.24,.13,v.cone);for(const z of [-.32,.32])parts.legs.push(block(c,side*.28,horse?.3:.2,z,.17,horse?.6:.4,.2));}
 const tail=ball(cat?0xd59b76:c,0,.75,.65,fox?.28:.12,fox?.25:.14,fox?.53:.4);tail.rotation.x=-.45;g.userData.tail=tail;
 if(s==='dog'){for(const side of [-1,1])ball(0x855737,side*.34,.91,-.43,.15,.33,.18);ball(0x483c39,0,.85,-.91,.12,.09,.06);}
 if(cat){tail.scale.set(.09,.12,.65);tail.rotation.x=-.9;for(const side of [-1,1])for(const dy of [-.06,.06]){const whisker=block(0xf6e9d3,side*.35,.84+dy,-.8,.35,.025,.025);whisker.rotation.z=side*dy*3;}}
 if(['fox','cosmicfox'].includes(s))ball(0xffead5,0,.95,.99,.2,.22,.27);
 if(s==='wolf'){ball(0x637c9c,0,.86,-.03,.42,.49,.33);ball(0xc8d6e0,0,.83,-.88,.23,.19,.32);}
 if(rabbit){ball(0xfff4eb,0,.65,.55,.24,.24,.24);for(const side of [-1,1])ball(0xefb7cd,side*.22,1.55,-.51,.06,.3,.04);}
 if(s==='cosmicfox'){const twin=ball(0xc9b3fa,.3,.8,.7,.18,.22,.55);twin.rotation.y=.6;}
 if(horse){ball(0xffdc85,0,1.65,-.62,.12,.5,.12,v.cone);for(let i=0;i<4;i++)ball(0xc5a0ee,0,1.4-i*.15,-.12,.14,.18,.2);}
 if(dragon){for(const side of [-1,1])parts.wings.push(ball(0xa4e4af,side*.58,.95,.1,.5,.08,.4));for(let i=0;i<4;i++)ball(0xffc469,0,.95,.15+i*.14,.1,.2,.12,v.cone);}
 if(s==='cosmicfox'){for(const side of [-1,1])ball(0x9bffff,side*.23,1.32,-.45,.06,.1,.07,v.gem);}
 }
 // Eyes face the same forward direction as the runner, with a visible side profile.
 for(const side of legacy?[-1,1]:[])ball(0x223752,side*.22,s==='sprite'?1.28:s==='golem'?1.2:s==='turtle'?.57:1.04,s==='turtle'?-.89:-.69,.065,.075,.055);
 const accessoryStart=g.children.length;const a=pet.accessories||{};if(a.head==='cap'){block(0xf6b967,0,1.48,-.3,.62,.18,.5);block(0xf6b967,0,1.45,-.61,.65,.07,.34);}if(a.head==='crown'){for(let i=0;i<3;i++)ball(0xffd877,(i-1)*.21,1.7,-.3,.12,.35,.12,v.cone);block(0xeab854,0,1.47,-.3,.65,.15,.5);}if(a.head==='wizard')ball(0x9986e8,0,1.8,-.3,.4,.8,.4,v.cone);if(a.head==='helmet')ball(0xa8ddf2,0,1.47,-.3,.48,.3,.42);
 if(a.neck){block(a.neck==='scarf'?0xf48488:0x80dbe2,0,.78,-.38,.65,.12,.4);if(['pendant','necklace'].includes(a.neck))ball(0xffe083,0,.64,-.63,.13,.18,.08,v.gem);if(a.neck==='scarf')block(0xf48488,.32,.48,-.38,.14,.45,.12);}
 if(a.back==='cape')block(0xe5769e,0,.7,.48,.7,.7,.08);if(a.back==='pack')block(0xffc66e,0,.78,.48,.5,.5,.28);if(a.back==='wings')for(const side of [-1,1])parts.wings.push(ball(0xfbe2ff,side*.56,.9,.3,.35,.55,.1));
 if(shape)for(const m of g.children.slice(accessoryStart)){m.position.y+=shape.head[1]-1.05;m.position.z+=shape.head[2]+.55;}if(s==='turtle')for(const m of g.children.slice(accessoryStart)){m.position.y-=.65;m.position.z-=.2;}const effects=new T.Group();g.add(effects);g.userData.effects=effects;if(a.effects||petLevel(pet.xp)>=5){for(let i=0;i<6;i++){const m=v.mesh(v.gem,a.effects==='paws'?0x9bffd5:0xf7d6ff,.8);m.scale.setScalar(.07);effects.add(m);}}
 if(type.rank>=3){for(let i=0;i<type.rank;i++){const m=v.mesh(v.gem,0xd5f7ff,.6);m.scale.setScalar(.06);effects.add(m);}}if(g.userData.aquatic){const bubble=new T.Group();for(let i=0;i<3;i++){const m=v.mesh(v.ring,0x9ee8fa,.25);m.scale.setScalar(1);m.position.y=.65;m.rotation.set(i===0?Math.PI/2:0,i===1?Math.PI/2:0,0);bubble.add(m);}g.add(bubble);g.userData.bubble=bubble;}g.scale.setScalar(.72+petLevel(pet.xp)*.013);return g;
}
export function animatePet(g,time,running,underwater=false){const d=g.userData;d.legs.forEach((l,i)=>l.rotation.x=running?Math.sin(time*12+i*Math.PI)*.45:Math.sin(time*2+i)*.05);d.wings.forEach((w,i)=>w.rotation.z=Math.sin(time*7)*(i%2?-.45:.45));for(const [i,t]of (d.tails||[]).entries())t.rotation.y=Math.sin(time*4+i)*.2;if(d.tail)d.tail.rotation.y=Math.sin(time*5)*.3;d.effects.children.forEach((m,i)=>m.position.set(Math.sin(time*2+i)*.65,.2+(i%3)*.4,Math.cos(time*2+i)*.65));g.position.y=(d.flying?1.5:underwater?.6:0)+Math.sin(time*(running?8:3))*(d.flying?.12:running?.07:.025);}
// Original vector portraits, with species-specific anatomy, used by touch menus.
export function petPortrait(id){const type=PETS.find(p=>p.id===id);if(!['dog','cat','fox','wolf','rabbit','owl','turtle','dragon','phoenix','unicorn','griffin','golem','cosmicfox','sprite'].includes(id))return expandedPortrait(type);const details={
 dog:'<ellipse cx="44" cy="63" rx="12" ry="24" fill="#855737"/><ellipse cx="108" cy="63" rx="12" ry="24" fill="#855737"/><ellipse cx="76" cy="72" rx="7" ry="5" fill="#493c39"/><path d="M73 81h7v9q-4 5-7 0" fill="#ef9baf"/>',
 cat:'<g stroke="#fff5de" stroke-width="2.5"><path d="M55 72L29 65m25 13L28 80m68-8l27-7m-27 13l27 2"/></g><path d="M39 108q-30-38-10-46" fill="none" stroke="#d59b76" stroke-width="10" stroke-linecap="round"/>',
 fox:'<path d="M103 112q49-3 34-50l-18 14q8 18-24 18" fill="#ef893e"/><path d="M137 62l-18 14 9 14 12-10z" fill="#fff1d8"/><path d="M50 67l15 9-10 8-10-11m57-6l-15 9 10 8 10-11" fill="#fff1d8"/>',
 wolf:'<path d="M48 84l-8 20 14-3 4 12 17-9 16 9 5-12 14 3-8-20-25 9z" fill="#c7d7e3"/><path d="M55 66l21 9 21-9-7 18H62z" fill="#e2edf0"/><ellipse cx="76" cy="72" rx="7" ry="4" fill="#344a63"/>',
 rabbit:'<ellipse cx="54" cy="28" rx="5" ry="17" fill="#eab1c5" transform="rotate(-13 54 28)"/><ellipse cx="100" cy="28" rx="5" ry="17" fill="#eab1c5" transform="rotate(13 100 28)"/><circle cx="119" cy="105" r="13" fill="#fff3f0"/><path d="M72 82h9v9h-9z" fill="white"/>',
 cosmicfox:'<path d="M103 111q48-4 34-47l-17 16q5 16-23 15M105 109q30-15 16-52l-14 18q5 16-12 21" fill="#c4aff9"/><path d="M118 39l4-11 4 11 11 4-11 4-4 11-4-11-11-4z" fill="#affff3"/>',
 dragon:'<path d="M68 38l8-15 8 15M102 110q31 9 25-24l-12 9q6 12-13 8" fill="#ffc165"/><path d="M64 100l12-13 12 13-12 13z" fill="#fae8a8"/>',
 griffin:'<path d="M43 88l-8 31h17l6-22m36-9l8 31h17l-10-31" fill="#bc955b"/><path d="M57 42q19-31 43 0l-8 7-16-7-13 8z" fill="#fff1d4"/>',
 unicorn:'<path d="M99 44q24 2 16 42l-13-9 3-18z" fill="#bda0e2"/><path d="M46 109h14v14H46m46-14h14v14H92" fill="#bda0e2"/>',
 phoenix:'<path d="M52 108l-2 22 20-16 6 19 9-20 19 17-8-25" fill="#ffd05a"/>',
 };return basePortrait(id).replace('</svg>',(details[id]||'')+'</svg>');}
function basePortrait(id){const p=PETS.find(p=>p.id===id)||PETS[0],c='#'+p.color.toString(16).padStart(6,'0');let anatomy='';if(id==='turtle')anatomy='<ellipse cx="75" cy="85" rx="47" ry="30" fill="#447e65"/><path d="M45 75l30-15 30 15-15 24H60z" fill="#aad18d"/><circle cx="126" cy="87" r="17" fill="'+c+'"/>';else if(id==='golem')anatomy='<path d="M43 58h65v53H43zM37 30h76v43H37zM22 65h18v44H22zM111 65h18v44h-18" fill="'+c+'"/><path d="M64 78l12-10 12 10-12 17z" fill="#a4ffeb"/>';else if(['owl','phoenix','griffin'].includes(id))anatomy='<ellipse cx="76" cy="81" rx="35" ry="44" fill="'+c+'"/><path d="M45 66L11 103l34-8M106 66l33 37-33-8" fill="'+c+'"/><circle cx="61" cy="58" r="15" fill="#fff2cd"/><circle cx="91" cy="58" r="15" fill="#fff2cd"/><path d="M68 73l8 13 8-13" fill="#ffc45c"/>'+(id==='phoenix'?'<path d="M53 35L64 9l12 23L89 8l10 30" fill="#ffc45c"/>':'');else if(id==='sprite')anatomy='<ellipse cx="48" cy="69" rx="25" ry="37" fill="#b4fbea"/><ellipse cx="105" cy="69" rx="25" ry="37" fill="#b4fbea"/><path d="M76 56l22 53H54z" fill="'+c+'"/><circle cx="76" cy="45" r="23" fill="#ffe1ba"/>';else anatomy='<ellipse cx="76" cy="93" rx="43" ry="25" fill="'+c+'"/><circle cx="76" cy="58" r="32" fill="'+c+'"/><path d="M48 44l-5-'+(id==='rabbit'?'42':'29')+' 25 20M84 32l24-'+(id==='rabbit'?'30':'17')+'-3 34" fill="'+c+'"/><ellipse cx="76" cy="72" rx="19" ry="12" fill="#fff0d9"/>'+(id==='unicorn'?'<path d="M71 31l6-29 7 29" fill="#ffe08c"/>':id==='dragon'?'<path d="M40 77L9 47l8 47M111 77l30-30-7 47" fill="#a8e3b7"/>':id==='cosmicfox'?'<path d="M20 22l4-10 4 10 10 4-10 4-4 10-4-10-10-4z" fill="#a9fff2"/>':'');return `<svg viewBox="0 0 152 135" role="img" aria-label="${p.species}"><ellipse cx="76" cy="122" rx="55" ry="8" fill="#061b3244"/>${anatomy}<circle cx="63" cy="59" r="4" fill="#22334b"/><circle cx="89" cy="59" r="4" fill="#22334b"/><path d="M70 77q6 7 12 0" fill="none" stroke="#30405a" stroke-width="3"/></svg>`;}
